#!/usr/bin/env python3
from pathlib import Path
import argparse,datetime,hashlib,json,shutil,sys
ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);a=ap.parse_args();R=a.root.resolve();C=R/'cegar'
def load(p):return json.loads(Path(p).read_text())
def dump(p,o):p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(o,indent=2,sort_keys=True)+'\n')
def sha_bytes(b):return hashlib.sha256(b).hexdigest()
def sha_obj(o):return sha_bytes(json.dumps(o,sort_keys=True,separators=(',',':')).encode())
rows=[];raw_index=[];retained=[];mechanisms=[];bindings=[];covers=[];process=[];corrections=[]
agg={k:0 for k in ['raw_term_candidates','retained_increment','literal_retained_tuple_replays','factorized_symbolically_proved_tuples','pair_domain_library_relative_new_tuples','participating_catalogs','local_order_records','structural_pair_relations','structural_pair_cells_represented','positive_pair_relations','unary_only_pair_relations','positive_pair_configurations','positive_pair_cells','multi_check_exact_relations','multi_check_terms_generated','pair_terms_generated','positive_finder_misses']}
ded={k:0 for k in ['raw_term_candidates','multi_check_candidates','pair_candidates','duplicate_old','duplicate_new','dominated_old','dominated_new','retained_increment']}
for i in range(42,54):
 d=C/f'iter{i}';o=load(d/'iteration_outcome.json');s=load(d/'generalization/summary.json');dl=load(d/'generalization/dedup_ledger.json');tr=load(d/'generalization/retained_terms.json')['terms'];m=load(d/'generalization/mechanisms.json')['mechanisms'];fb=load(d/'generalization/formula_raw_replay_bindings.json')['records'];tu=load(d/'generalization/tuple_raw_replay.json')['terms'];rc=load(d/'generalization/raw_term_candidates.json')['terms']
 for k in agg:agg[k]+=s[k]
 for k in ded:ded[k]+=dl[k]
 retained.extend(tr);mechanisms.extend(m);bindings.extend(fb)
 raw_index.append({'iteration':i,'path':f'cegar/iter{i}/generalization/raw_term_candidates.json.gz','terms':len(rc),'semantic_sha256':sha_obj(rc),'file_uncompressed_sha256':sha_bytes((d/'generalization/raw_term_candidates.json').read_bytes())})
 for mm in m:
  covers.append({'iteration':i,'mechanism_id':mm['mechanism_id'],'sector':mm['sector'],'fault_count':mm['fault_count'],'covering_installed_term_ids':mm['installed_generalized_cover_ids'],'covering_new_term_ids':mm['new_retained_cover_ids'],'exact_only':not bool(mm['new_retained_cover_ids'])})
 for r in o['process_records']:
  z=dict(r);process.append(z)
 for r in o.get('correction_records',[]):corrections.append(dict(r))
 rows.append({'iteration':i,'outer_status':o['outer_status'],'outer_seconds':o['outer_seconds'],'candidate_sha256':o['candidate_sha256'],'installed_blocks_before':o['installed_blocks_before'],'installed_blocks_after':o['installed_blocks_after'],'dynamic_before':o['dynamic_blocks_before'],'dynamic_after':o['dynamic_blocks_after'],'generalized_before':o['generalized_terms_before'],'generalized_after':o['generalized_terms_after'],'retained_increment':o['online_generalized_retained_increment'],'Xerr_status':o['sector_statuses']['Xerr'],'Zerr_status':o['sector_statuses']['Zerr'],'Xerr_weight':o['sector_fault_weights']['Xerr'],'Zerr_weight':o['sector_fault_weights']['Zerr'],'raw_candidates':s['raw_term_candidates'],'literal_tuple_replays':s['literal_retained_tuple_replays'],'factorized_symbolic_tuples':s['factorized_symbolically_proved_tuples'],'pair_library_relative_new_tuples':s['pair_domain_library_relative_new_tuples'],'strict_stage_order':o['strict_stage_order']})
assert len(retained)==134 and len(mechanisms)==len(bindings)==24 and len(process)==84 and len(corrections)==3
final_dyn=load(C/'dynamic_blocks.json');final_gen=load(R/'classification/installed_generalized_terms.json');registry=load(R/'classification/online_mechanism_registry.json')
assert len(final_dyn)==108 and final_gen['term_count']==5440 and registry['mechanism_count']==24
cegar_summary={'schema':'round74-online-cegar-summary-v1','status':'PASS','iteration_range':[42,53],'completed_dual_sector_candidates':12,'outer_verdicts':{'SAT':12,'UNSAT':0,'UNKNOWN':0,'TIMEOUT':0},'direct_sector_verdicts':{'SATISFIABLE':24,'UNSAT_PROOFS_ACCEPTED':0,'UNKNOWN_OR_TIMEOUT':0},'assignment_clause_replays':24,'raw_canonical_physical_replays':24,'candidate_exact_blocks_added':24,'accepted_absence_proofs':0,'repair_entered':False,'branch_closed':False,'root_closed':False,'iterations':rows,'restart':{'next_iteration':54,'round63_unary_blocks':1440,'round62_blocks':20,'round69_generalized_blocks':4740,'round72_generalized_blocks':566,'round74_generalized_blocks':134,'merged_generalized_blocks':5440,'dynamic_blocks_total':108,'dynamic_blocks_inherited_round72':84,'dynamic_blocks_new_round74':24,'exploratory_round63_pair_clauses_installed':0,'next_outer_total_blocks':7008,'dynamic_state':'cegar/dynamic_blocks.json','generalized_state':'classification/installed_generalized_terms.json','registry_state':'classification/online_mechanism_registry.json'}}
dump(C/'summary.json',cegar_summary)
class_summary={'schema':'round74-online-generalization-aggregate-summary-v1','status':'PASS','iteration_range':[42,53],'source_mechanisms':24,'formula_assignment_raw_replays':24,'candidate_exact_blocks_preserved':24,'old_reviewed_generalized_terms':5306,'round74_retained_terms':134,'merged_installed_generalized_terms':5440,'weight14_positive_pool_counts':{'Xerr':9438,'Zerr':9435},'weight14_negative_results_used':0,'zero_truth_cells_used_as_absence':0,'positive_finder_misses_used_as_absence':0,'deletion_countertuples_used_as_absence':0,'joint_multi_check_dp':True,'factorized_multi_validation_is_symbolic_universal_not_sampling':True,**agg,'retained_deletion_controls':sum(len(t['deletion_controls']) for t in retained),'retained_relation_kinds':{k:sum(t['relation_kind']==k for t in retained) for k in ['positive_pair_rectangle','multi_check_exact_selected_mechanism']},'mechanisms_with_installed_generalized_cover':sum(bool(x['new_retained_cover_ids']) for x in mechanisms),'mechanisms_exact_only':sum(not bool(x['new_retained_cover_ids']) for x in mechanisms),'claim_scope':'positive sound online generalization and exact candidate progress only; no absence, exhaustion, or root closure'}
dump(R/'classification/summary.json',class_summary)
dump(R/'classification/dedup_ledger.json',{'schema':'round74-online-dedup-aggregate-v1','iteration_range':[42,53],'old_reviewed_terms':5306,'previous_round74_retained_terms_at_start':0,'installed_generalized_after':5440,**ded,'per_iteration':[{'iteration':r['iteration'],**{k:load(C/f"iter{r['iteration']}/generalization/dedup_ledger.json")[k] for k in ded}} for r in rows],'semantic_definition':'finite products of exact 720-order masks; U dominates V iff region(V) subset region(U); predecessors never removed','raw_candidate_file_index':raw_index})
dump(R/'classification/round74_retained_terms.json',{'schema':'round74-retained-generalized-terms-aggregate-v1','terms':retained})
dump(R/'classification/round74_mechanisms.json',{'schema':'round74-source-mechanisms-aggregate-v1','mechanisms':mechanisms})
dump(R/'classification/round74_formula_raw_replay_bindings.json',{'schema':'round74-formula-assignment-raw-replay-bindings-aggregate-v1','records':bindings})
dump(R/'classification/source_mechanism_cover.json',{'schema':'round74-source-mechanism-cover-v1','records':covers,'all_covered':all(x['covering_installed_term_ids'] for x in covers)})
# Process rows are successful load-bearing stages only; corrections are explicit and excluded from online order.
for a1,b1 in zip(process,process[1:]):assert a1['ended_utc']<=b1['started_utc']
dump(R/'PROCESS_LEDGER.json',{'schema':'round74-process-ledger-v1','strict_foreground_serial':True,'detached_processes':0,'candidate_process_records':process,'correction_records':corrections,'candidate_records':len(process),'candidate_exit_10_sat':sum(x['exit_code']==10 for x in process),'candidate_exit_0':sum(x['exit_code']==0 for x in process),'candidate_timeouts':sum(x['timed_out'] for x in process),'candidate_signals':sum(x['sigterm_sent'] or x['sigkill_sent'] for x in process),'correction_policy':'all correction attempts are retained; no generalized/registry state changed before the successful attempt; exact dynamic state changed once at the specified stage'})
# Freeze both current and explicit iteration54 restart copies.
for src,name in [(C/'dynamic_blocks.json','dynamic_blocks_iteration54.json'),(R/'classification/installed_generalized_terms.json','installed_generalized_terms_iteration54.json'),(R/'classification/online_mechanism_registry.json','online_mechanism_registry_iteration54.json')]:shutil.copy2(src,R/'restart'/name)
dump(R/'restart/restart_state.json',{'schema':'round74-exact-restart-state-v1','next_iteration':54,'total_installed_blocks':7008,'counts':{'round63_unary':1440,'round62':20,'round69_generalized':4740,'round72_generalized':566,'round74_generalized':134,'merged_generalized':5440,'dynamic_exact':108,'exploratory_round63_pair':0},'states':{'dynamic':'restart/dynamic_blocks_iteration54.json','generalized':'restart/installed_generalized_terms_iteration54.json','mechanism_registry':'restart/online_mechanism_registry_iteration54.json'},'license':'restart only after a fresh review accepts this candidate package; package does not close the root'})
print(json.dumps({'cegar':cegar_summary['restart'],'classification':class_summary,'processes':len(process),'corrections':len(corrections)},sort_keys=True))
